---@class ShipFloat

local ShipFloat = Class('ShipFloat')
local KTool = CS.Engine.Lib.KTool
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local Time = CS.UnityEngine.Time
local IDComp = CS.Game.Native.Common.ID
-- Mathf 已经在 Init.lua 中声明了, 可直接用;

-- ==============================
-- 目前存在两套参数, 每个船实例从 c# 端传入一个 id值 (int), 依据此 id 值选择一份参数来使用;
local paramsArray = {
    -- 1 --
    {
        timeOffset = 1.0,
        floatSpeed = 0.5,
        floatRange = 0.15,
        x_Speed = 9.0,
        z_Speed = 9.0
    },
    -- 2 --
    {
        timeOffset = 3.0,
        floatSpeed = 0.4,
        floatRange = 0.12,
        x_Speed = 9.0,
        z_Speed = 5.0
    },
    -- 3 --
    {
        timeOffset = 2.0,
        floatSpeed = 0.35,
        floatRange = 0.13,
        x_Speed = 9.0,
        z_Speed = 6.0
    }
}

local TWO_PI = 6.283185
local heighNow = 0.0  -- 临时变量

function ShipFloat:__init()
    --printInfo("   ~~~~~~~ ShipFloat:__init() ~~~~~~~")
    self.id = nil
    self.controller = nil
end

function ShipFloat:__delete()
    --printInfo("   ~~~~~~~ ShipFloat:__delete() ~~~~~~~")
    self.id = nil
end

function ShipFloat:Awake()
    --printInfo("   ~~~~~~~ ShipFloat:Awake() ~~~~~~~")
    KTool.SetActive(self.controller.gameObject, true);
end

function ShipFloat:Start()
    KTool.SetActive(self.controller.gameObject, true);
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ==============================
    -- 从 c# 端获得 id 值, 使用此值来选择不同的 params
    local idComp = self.controller.gameObject:GetComponent(typeof(IDComp))
    if isNull(idComp) then
        self.id = 0
    else 
        self.id = idComp.id
    end
    -- =============================
    heighNow = self.controller.transform.position.y
    --printInfo("   ~~~~~~~ ShipFloat:Start() ~~~~~~~")
end

function ShipFloat:Update()
    --printInfo("   ~~~~~~~ ShipFloat:Update()  ~~~~~~~")

    local paramsArrayLen = #paramsArray -- int
    local idx = (self.id%paramsArrayLen)+1 -- N选一
    local params = paramsArray[idx]
    
    -- 主要内容部分, 可以正常运行了
    local t = ((Time.timeSinceLevelLoad + params["timeOffset"]) * params["floatSpeed"]) % 1.0 * TWO_PI
    local y = Mathf.Sin(t) * params["floatRange"] + heighNow
    local r = Mathf.Sin(t) * params["floatRange"]

    local pos = self.controller.transform.position
    self.controller.transform.position = Vector3.New( pos.x, y, pos.z )
    self.controller.transform:Rotate( r * params["x_Speed"] / 100.0, 0.0, r * params["z_Speed"] / 100.0 )
    --print( "t = "..t..", r = "..r )
end

function ShipFloat:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象 --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    printInfo("   ~~~~~~~ ShipFloat:OnDestroy() ~~~~~~~")
end

return ShipFloat
